def authorize(workspace_id, actor, action, resource, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0179000" if __import__("os").path.isdir("./environment_mix/0179000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        t = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        rnd = os.urandom(8).hex()
        return f"{prefix}_{t}_{rnd}"

    def _extract_type_id(obj):
        if not isinstance(obj, dict):
            return None, None
        t = obj.get("type") or obj.get("kind") or obj.get("_type") or obj.get("resource_type")
        i = obj.get("id") or obj.get("_id")
        if t is None and isinstance(obj.get("type"), str):
            t = obj.get("type")
        if t is not None and not isinstance(t, str):
            t = None
        if i is not None and not isinstance(i, str):
            i = None
        return t, i

    start = time.time()
    created_at = _now_iso()

    # Validate input
    if not isinstance(workspace_id, str) or not re.match(r"^oso_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is missing or invalid format", field="workspace_id")
    if not isinstance(actor, dict):
        return _err("VALIDATION_ERROR", "actor must be an object", field="actor")
    if not isinstance(action, str) or not action:
        return _err("VALIDATION_ERROR", "action must be a non-empty string", field="action")
    if not isinstance(resource, dict):
        return _err("VALIDATION_ERROR", "resource must be an object", field="resource")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id)

    api_keys = _load("api_keys.json")
    key_row = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key_row:
        # Log error then UNAUTHORIZED
        checks = _load("authorization_checks.json")
        latency_ms = max(0, int((time.time() - start) * 1000))
        checks.append({
            "id": _gen_id("oso_chk"),
            "workspace_id": workspace_id,
            "api_key_id": None,
            "policy_id": ws.get("current_policy_id"),
            "tool": "authorize",
            "actor": actor,
            "action": action,
            "resource": resource,
            "resource_type": None,
            "result_allowed": None,
            "result_resource_ids": None,
            "result_actions": None,
            "latency_ms": latency_ms,
            "status": "error",
            "error_code": "unauthorized",
            "error_message": "No active API key available for workspace",
            "created_at": created_at,
            "updated_at": created_at
        })
        _save("authorization_checks.json", checks)
        return _err("UNAUTHORIZED", "caller is not authenticated for this workspace")

    # Rate limiting: per workspace + tool family
    quota = ws.get("quota_authorize_per_minute")
    if not isinstance(quota, int) or quota < 0:
        quota = 0

    checks = _load("authorization_checks.json")
    now_dt = _parse_iso(created_at)
    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for c in checks:
        if c.get("workspace_id") != workspace_id:
            continue
        if c.get("tool") != "authorize":
            continue
        c_dt = _parse_iso(c.get("created_at"))
        if c_dt and c_dt > window_start:
            recent += 1

    if recent >= quota:
        latency_ms = max(0, int((time.time() - start) * 1000))
        checks.append({
            "id": _gen_id("oso_chk"),
            "workspace_id": workspace_id,
            "api_key_id": key_row.get("id"),
            "policy_id": ws.get("current_policy_id"),
            "tool": "authorize",
            "actor": actor,
            "action": action,
            "resource": resource,
            "resource_type": None,
            "result_allowed": None,
            "result_resource_ids": None,
            "result_actions": None,
            "latency_ms": latency_ms,
            "status": "rate_limited",
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded",
            "created_at": created_at,
            "updated_at": created_at
        })
        _save("authorization_checks.json", checks)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Evaluate
    policies = _load("policies.json")
    policy_id = ws.get("current_policy_id")
    policy_row = None
    if policy_id:
        policy_row = next((p for p in policies if p.get("id") == policy_id and p.get("workspace_id") == workspace_id), None)
        if policy_row and policy_row.get("status") != "active":
            policy_row = None

    # Simple tuple-based evaluation:
    # allow if there exists active tuple matching:
    # subject_type/id (from actor), relation==action, object_type/id (from resource),
    # object_subrelation matches if provided in resource (resource["subrelation"] / "object_subrelation")
    # Validity window enforced.
    default_decision = ws.get("default_decision", "deny")
    allowed = True if default_decision == "allow" else False

    actor_type, actor_id = _extract_type_id(actor)
    res_type, res_id = _extract_type_id(resource)
    res_subrel = None
    if isinstance(resource, dict):
        res_subrel = resource.get("object_subrelation") or resource.get("subrelation")
        if res_subrel is not None and not isinstance(res_subrel, str):
            res_subrel = None

    tuples = _load("authz_tuples.json")
    if policy_row:
        # only attempt tuple evaluation when a policy is active; otherwise use default_decision.
        # If actor/resource missing type/id, fall back to default_decision.
        if actor_type and actor_id and res_type and res_id:
            now_dt = _parse_iso(created_at)
            match = False
            for t in tuples:
                if t.get("workspace_id") != workspace_id:
                    continue
                if t.get("status") != "active":
                    continue
                if t.get("subject_type") != actor_type or t.get("subject_id") != actor_id:
                    continue
                if t.get("relation") != action:
                    continue
                if t.get("object_type") != res_type or t.get("object_id") != res_id:
                    continue
                t_sub = t.get("object_subrelation")
                if (t_sub or None) != (res_subrel or None):
                    continue
                vf = _parse_iso(t.get("valid_from"))
                vt = _parse_iso(t.get("valid_to"))
                if vf and now_dt and now_dt < vf:
                    continue
                if vt and now_dt and now_dt >= vt:
                    continue
                match = True
                break
            allowed = match
        # else keep allowed as default? In tuple-only mode, lack of identity means deny.
        else:
            allowed = False

    latency_ms = max(0, int((time.time() - start) * 1000))

    # Log
    checks.append({
        "id": _gen_id("oso_chk"),
        "workspace_id": workspace_id,
        "api_key_id": key_row.get("id"),
        "policy_id": policy_row.get("id") if policy_row else None,
        "tool": "authorize",
        "actor": actor,
        "action": action,
        "resource": resource,
        "resource_type": None,
        "result_allowed": bool(allowed),
        "result_resource_ids": None,
        "result_actions": None,
        "latency_ms": latency_ms,
        "status": "success" if allowed else "denied",
        "error_code": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at
    })
    _save("authorization_checks.json", checks)

    # Update last_used_at for chosen key on successful processing (even if denied)
    now = _now_iso()
    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    return {
        "workspace_id": workspace_id,
        "allowed": bool(allowed),
        "policy_id": policy_row.get("id") if policy_row else None
    }

