    tuples = _load("authz_tuples.json")

    result_ids = []
    if policy_row and actor_type and actor_id:
        # Enumerate all objects of resource_type that have an active tuple allowing (actor, action, object)
        seen = set()
        for t in tuples:
            if t.get("workspace_id") != workspace_id:
                continue
            if t.get("status") != "active":
                continue
            if t.get("relation") != action:
                continue
            if t.get("subject_type") != actor_type or t.get("subject_id") != actor_id:
