            vf = _parse_iso(t.get("valid_from"))
            vt = _parse_iso(t.get("valid_to"))
            if vf and now_dt and now_dt < vf:
                continue
            if vt and now_dt and now_dt >= vt:
                continue
            oid = t.get("object_id")
            if isinstance(oid, str) and oid and oid not in seen:
                seen.add(oid)
                result_ids.append(oid)
    else:
        # No active policy => default_decision governs, but we cannot enumerate all resources without a catalog.
        # Real service would be policy-driven; in this datastore, tuples are the only resource universe.
        # If default allow and no policy, list the universe (tuples' object_ids) for that type; else empty.
        if ws.get("default_decision") == "allow":
            seen = set()
            for t in tuples:
                if t.get("workspace_id") != workspace_id:
                    continue
                if t.get("status") != "active":
                    continue
                if t.get("object_type") != resource_type:
                    continue
                oid = t.get("object_id")
                if isinstance(oid, str) and oid and oid not in seen:
                    seen.add(oid)
                    result_ids.append(oid)

    latency_ms = max(0, int((time.time() - start) * 1000))

    # Log (may truncate result_resource_ids)
    sample = result_ids[:1000]
    checks.append({
        "id": _gen_id("oso_chk"),
        "workspace_id": workspace_id,
        "api_key_id": key_row.get("id"),
        "policy_id": policy_row.get("id") if policy_row else None,
        "tool": "list_resources",
        "actor": actor,
        "action": action,
        "resource": None,
        "resource_type": resource_type,
        "result_allowed": None,
        "result_resource_ids": sample,
        "result_actions": None,
        "latency_ms": latency_ms,
        "status": "success",
        "error_code": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at
    })
    _save("authorization_checks.json", checks)

    # Update last_used_at
    now = _now_iso()
    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Endpoint returns full result set (no pagination)
    return {
        "workspace_id": workspace_id,
        "resource_type": resource_type,
        "resource_ids": result_ids,
        "policy_id": policy_row.get("id") if policy_row else None
    }

