            if vf and now_dt and now_dt < vf:
                continue
            if vt and now_dt and now_dt >= vt:
                continue
            rel = t.get("relation")
            if isinstance(rel, str) and rel and rel not in seen:
                seen.add(rel)
                allowed_actions.append(rel)
        allowed_actions.sort()
    else:
        # No active policy: default allow/deny. Without an action catalog, we can only return empty
        # (deny) or the set of relations present in tuples for this actor/resource (allow-ish).
        if ws.get("default_decision") == "allow" and actor_type and actor_id and res_type and res_id:
            seen = set()
            for t in tuples:
                if t.get("workspace_id") != workspace_id:
                    continue
                if t.get("status") != "active":
                    continue
                if t.get("subject_type") != actor_type or t.get("subject_id") != actor_id:
                    continue
                if t.get("object_type") != res_type or t.get("object_id") != res_id:
                    continue
                if (t.get("object_subrelation") or None) != (res_subrel or None):
                    continue
                rel = t.get("relation")
                if isinstance(rel, str) and rel and rel not in seen:
                    seen.add(rel)
                    allowed_actions.append(rel)
            allowed_actions.sort()

    latency_ms = max(0, int((time.time() - start) * 1000))

    checks.append({
        "id": _gen_id("oso_chk"),
        "workspace_id": workspace_id,
        "api_key_id": key_row.get("id"),
        "policy_id": policy_row.get("id") if policy_row else None,
        "tool": "get_actions",
        "actor": actor,
        "action": None,
        "resource": resource,
        "resource_type": None,
        "result_allowed": None,
        "result_resource_ids": None,
        "result_actions": allowed_actions[:1000],
        "latency_ms": latency_ms,
        "status": "success",
        "error_code": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at
    })
    _save("authorization_checks.json", checks)

    now = _now_iso()
    for k in api_keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    return {
        "workspace_id": workspace_id,
        "actions": allowed_actions,
        "policy_id": policy_row.get("id") if policy_row else None
    }

def whoami(api_key=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0179000" if __import__("os").path.isdir("./environment_mix/0179000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random
        ts = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ts % 32])
            ts //= 32
        for _ in range(10):
            chars.append(random.choice(alphabet))
        return f"{prefix}{''.join(reversed(chars))}"

    t0 = time.perf_counter()
    now = _now()

    # Resolve API key (explicit required for whoami)
    if api_key is None:
        # "If omitted, server uses configuration when available" - no config store provided; require explicit.
        # Log attempt without workspace association isn't possible (rule says exactly one workspace per invocation).
        # Return UNAUTHORIZED without log.
        return _err("UNAUTHORIZED", "API key is required for whoami")

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_key_in = api_key.strip()

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    checks = _load("authorization_checks.json")

    # Authenticate by matching client-visible value or id.
    # Store has id and key_prefix; cannot validate key_hash. Accept id exact or prefix match.
    key_row = None
    if api_key_in.startswith("oso_key_"):
        key_row = next((k for k in api_keys if k.get("id") == api_key_in), None)
    if key_row is None:
        key_row = next((k for k in api_keys if k.get("key_prefix") == api_key_in), None)

    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    ws = next((w for w in workspaces if w.get("id") == key_row.get("workspace_id")), None)
    if ws is None or ws.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Workspace not available for this API key")

    # Handle revoked key: must be logged as error with code api_key_revoked
    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
    if key_row.get("status") == "revoked":
        check = {
            "id": _gen_id("oso_chk_"),
            "workspace_id": ws.get("id"),
            "api_key_id": key_row.get("id"),
            "policy_id": ws.get("current_policy_id"),
            "tool": "get_policy",  # closest tool family for metadata; schema enum doesn't include whoami
            "actor": None,
            "action": None,
            "resource": None,
            "resource_type": None,
            "result_allowed": None,
            "result_resource_ids": None,
            "result_actions": None,
            "latency_ms": latency_ms,
            "status": "error",
            "error_code": "api_key_revoked",
            "error_message": "API key is revoked",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        checks.append(check)
        _save("authorization_checks.json", checks)
        return _err("UNAUTHORIZED", "API key is revoked", error_code="api_key_revoked")

    # Rate limit/quota consumption snapshot per family based on authorization_checks last minute
    window_start = now - datetime.timedelta(minutes=1)

    def _count(tool_name):
        c = 0
        for r in checks:
            if r.get("workspace_id") != ws.get("id"):
                continue
            if r.get("tool") != tool_name:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= window_start:
                c += 1
        return c

    authorize_used = _count("authorize")
    list_used = _count("list_resources")
    actions_used = _count("get_actions")

    quota_authorize = int(ws.get("quota_authorize_per_minute") or 0)
    quota_list = int(ws.get("quota_list_per_minute") or 0)
    quota_actions = int(ws.get("quota_actions_per_minute") or 0)

    # Log the whoami call as get_policy tool (schema limitation). Mark success.
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = key_row.get("updated_at") or _iso(now)
    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
    check = {
        "id": _gen_id("oso_chk_"),
        "workspace_id": ws.get("id"),
        "api_key_id": key_row.get("id"),
        "policy_id": ws.get("current_policy_id"),
        "tool": "get_policy",  # schema enum
        "actor": None,
        "action": None,
        "resource": None,
        "resource_type": None,
        "result_allowed": None,
        "result_resource_ids": None,
        "result_actions": None,
        "latency_ms": latency_ms,
        "status": "success",
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    checks.append(check)
    _save("authorization_checks.json", checks)

    return {
        "caller": {
            "api_key_id": key_row.get("id"),
            "api_key_name": key_row.get("name"),
            "api_key_prefix": key_row.get("key_prefix"),
            "workspace": {
                "id": ws.get("id"),
                "name": ws.get("name"),
                "status": ws.get("status"),
                "current_policy_id": ws.get("current_policy_id"),
                "default_decision": ws.get("default_decision"),
            },
            "scopes": ["read:workspace", "read:policy", "write:policy", "write:authz_tuples"],
        },
        "rate_limits": {
            "window_seconds": 60,
            "authorize": {
                "used": authorize_used,
                "quota": quota_authorize,
                "remaining": max(0, quota_authorize - authorize_used),
            },
            "list_resources": {
                "used": list_used,
                "quota": quota_list,
                "remaining": max(0, quota_list - list_used),
            },
            "get_actions": {
                "used": actions_used,
                "quota": quota_actions,
                "remaining": max(0, quota_actions - actions_used),
            },
        },
    }

def create_policy(workspace_id, polar_source, version=None, **_extra):
    import json, os, datetime, re, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0179000" if __import__("os").path.isdir("./environment_mix/0179000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ts % 32])
            ts //= 32
        for _ in range(10):
            chars.append(random.choice(alphabet))
        return f"{prefix}{''.join(reversed(chars))}"

    t0 = time.perf_counter()
    now = _now()

    if not isinstance(workspace_id, str):
        return _err("VALIDATION_ERROR", "workspace_id must be a string")
    if not re.match(r"^oso_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match expected oso_ws_… ULID format")
    if not isinstance(polar_source, str) or not polar_source.strip():
        return _err("VALIDATION_ERROR", "polar_source must be a non-empty string")
    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string when provided")

    workspaces = _load("workspaces.json")
    policies = _load("policies.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Workspace not found")

    # Assign monotonically increasing integer version within workspace
    existing = [p for p in policies if p.get("workspace_id") == workspace_id]
    max_ver = 0
    for p in existing:
        try:
            max_ver = max(max_ver, int(p.get("version") or 0))
        except Exception:
            pass
    new_ver = max_ver + 1
    if new_ver < 1:
        new_ver = 1

    source_sha = hashlib.sha256(polar_source.encode("utf-8")).hexdigest()

    # Enforce unique(workspace_id, source_sha256)
    if any(p.get("workspace_id") == workspace_id and p.get("source_sha256") == source_sha for p in policies):
        return _err("CONFLICT", "A policy with identical source already exists in this workspace", field="source_sha256")

    policy_id = _gen_id("oso_pol_")
    row = {
        "id": policy_id,
        "workspace_id": workspace_id,
        "version": new_ver,
        "polar_source": polar_source,
        "source_sha256": source_sha,
        "status": "draft",
        "compiled_at": None,
        "activated_at": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    policies.append(row)
    _save("policies.json", policies)

    # Log invocation (schema constraint: tool enum lacks create_policy; map to get_policy to maintain logs)
    checks = _load("authorization_checks.json")
    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
    check = {
        "id": _gen_id("oso_chk_"),
        "workspace_id": workspace_id,
        "api_key_id": None,
        "policy_id": ws.get("current_policy_id"),
        "tool": "get_policy",
        "actor": None,
        "action": None,
        "resource": None,
        "resource_type": None,
        "result_allowed": None,
        "result_resource_ids": None,
        "result_actions": None,
        "latency_ms": latency_ms,
        "status": "success",
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    checks.append(check)
    _save("authorization_checks.json", checks)

    # Return created policy record + client label if provided
    out = dict(row)
    if version is not None:
        out["client_version_label"] = version
    return {"policy": out}

def upsert_authz_tuples(workspace_id, tuples, mode=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0179000" if __import__("os").path.isdir("./environment_mix/0179000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ts % 32])
            ts //= 32
        for _ in range(10):
            chars.append(random.choice(alphabet))
        return f"{prefix}{''.join(reversed(chars))}"

    def _key(t):
        return (
            t.get("subject_type"),
            t.get("subject_id"),
            t.get("relation"),
            t.get("object_type"),
            t.get("object_id"),
            t.get("object_subrelation"),
        )

    t0 = time.perf_counter()
    now = _now()

    if not isinstance(workspace_id, str) or not re.match(r"^oso_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match expected oso_ws_… ULID format")
    if not isinstance(tuples, list):
        return _err("VALIDATION_ERROR", "tuples must be an array")
    if mode is None:
        mode = "upsert"
    if mode not in ("upsert", "replace"):
        return _err("VALIDATION_ERROR", "mode must be one of 'upsert' or 'replace'")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Workspace not found")

    # Validate tuple items
    normalized = []
    seen_keys = set()
    for idx, t in enumerate(tuples):
        if not isinstance(t, dict):
            return _err("VALIDATION_ERROR", f"tuples[{idx}] must be an object")
        for req in ("subject_type", "subject_id", "relation", "object_type", "object_id"):
            if req not in t:
                return _err("VALIDATION_ERROR", f"tuples[{idx}].{req} is required")
            if not isinstance(t.get(req), str) or not t.get(req).strip():
                return _err("VALIDATION_ERROR", f"tuples[{idx}].{req} must be a non-empty string")

        obj_sub = t.get("object_subrelation", None)
        if obj_sub is not None and (not isinstance(obj_sub, str) or not obj_sub.strip()):
            return _err("VALIDATION_ERROR", f"tuples[{idx}].object_subrelation must be a non-empty string when provided")

        st = t.get("status", "active")
        if st not in ("active", "deleted"):
            return _err("VALIDATION_ERROR", f"tuples[{idx}].status must be 'active' or 'deleted'")

        vf = t.get("valid_from", None)
        vt = t.get("valid_to", None)
        vf_dt = _parse_dt(vf) if vf is not None else None
        vt_dt = _parse_dt(vt) if vt is not None else None
        if vf is not None and vf_dt is None:
            return _err("VALIDATION_ERROR", f"tuples[{idx}].valid_from must be RFC3339 date-time")
        if vt is not None and vt_dt is None:
            return _err("VALIDATION_ERROR", f"tuples[{idx}].valid_to must be RFC3339 date-time")
        if vf_dt is not None and vt_dt is not None and not (vf_dt < vt_dt):
            return _err("VALIDATION_ERROR", f"tuples[{idx}] must satisfy valid_from < valid_to")

        nt = {
            "subject_type": t["subject_type"].strip(),
            "subject_id": t["subject_id"].strip(),
            "relation": t["relation"].strip(),
            "object_type": t["object_type"].strip(),
            "object_id": t["object_id"].strip(),
            "object_subrelation": obj_sub.strip() if isinstance(obj_sub, str) else None,
            "valid_from": _iso(vf_dt) if vf_dt is not None else None,
            "valid_to": _iso(vt_dt) if vt_dt is not None else None,
            "status": st,
        }
        k = _key(nt)
        if k in seen_keys:
            return _err("VALIDATION_ERROR", f"Duplicate tuple in request at tuples[{idx}] for the same identity key")
        seen_keys.add(k)
        normalized.append(nt)

    store = _load("authz_tuples.json")

    # Index existing by key within workspace
    existing = {}
    for i, row in enumerate(store):
        if row.get("workspace_id") != workspace_id:
            continue
        existing[_key(row)] = (i, row)

    inserted = 0
    updated = 0
    deleted = 0

    if mode == "replace":
        # Mark any existing tuples not present in request as deleted (soft delete)
        incoming_keys = set(_key(t) for t in normalized)
        for k, (i, row) in list(existing.items()):
            if k in incoming_keys:
                continue
            if row.get("status") != "deleted":
                row["status"] = "deleted"
                row["updated_at"] = _iso(now)
                store[i] = row
                deleted += 1

    # Upsert incoming tuples
    for t in normalized:
        k = _key(t)
        if k in existing:
            i, row = existing[k]
            # Update mutable fields: status, valid_from/to
            changed = False
            for fld in ("status", "valid_from", "valid_to"):
                if row.get(fld) != t.get(fld):
                    row[fld] = t.get(fld)
                    changed = True
            if changed:
                row["updated_at"] = _iso(now)
                store[i] = row
                updated += 1
                if row.get("status") == "deleted":
                    # count as deleted if transitioned active->deleted (or set deleted)
                    # don't double count if already deleted and unchanged
                    pass
            # refresh existing mapping row
            existing[k] = (i, row)
        else:
            new_id = _gen_id("oso_tpl_")
            row = {
                "id": new_id,
                "workspace_id": workspace_id,
                "subject_type": t["subject_type"],
                "subject_id": t["subject_id"],
                "relation": t["relation"],
                "object_type": t["object_type"],
                "object_id": t["object_id"],
                "object_subrelation": t.get("object_subrelation"),
                "status": t.get("status", "active"),
                "valid_from": t.get("valid_from"),
                "valid_to": t.get("valid_to"),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            store.append(row)
            inserted += 1
            existing[k] = (len(store) - 1, row)

    # Count deletions due to incoming status=deleted transitions among updated/inserted?
    # API expects deleted count of records set to deleted in this call:
    # - in replace: those marked deleted above
    # - in upsert: tuples provided with status=deleted that either inserted or changed from active->deleted
    # We'll compute it precisely by tracking transitions.
    # Re-scan only keys affected in request for active->deleted transitions.
    for t in normalized:
        if t.get("status") != "deleted":
            continue
        k = _key(t)
        i, row = existing[k]
        # If inserted with deleted, count as deleted as well (considered a deleted record written)
        # If updated to deleted, count as deleted.
        # We can approximate: if row.status == deleted and row.updated_at == now OR created_at == now
        if row.get("status") == "deleted":
            # Count if created or updated at 'now' timestamp we just used
            if row.get("created_at") == _iso(now) or row.get("updated_at") == _iso(now):
                deleted += 1

    _save("authz_tuples.json", store)

    # Log invocation (schema tool enum lacks upsert_authz_tuples; map to get_policy)
    checks = _load("authorization_checks.json")
    latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
    check = {
        "id": _gen_id("oso_chk_"),
        "workspace_id": workspace_id,
        "api_key_id": None,
        "policy_id": ws.get("current_policy_id"),
        "tool": "get_policy",
        "actor": None,
        "action": None,
        "resource": None,
        "resource_type": None,
        "result_allowed": None,
        "result_resource_ids": None,
        "result_actions": None,
        "latency_ms": latency_ms,
        "status": "success",
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    checks.append(check)
    _save("authorization_checks.json", checks)

    return {"counts": {"inserted": inserted, "updated": updated, "deleted": deleted}, "mode": mode, "workspace_id": workspace_id}

def list_authorization_checks(workspace_id, tool=None, status=None, api_key_id=None, policy_id=None, action=None, resource_type=None, since=None, until=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0179000" if __import__("os").path.isdir("./environment_mix/0179000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.perf_counter()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("not a string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(ss)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _to_dt_maybe(v):
        if v is None:
            return None
        if isinstance(v, str):
            try:
                return _parse_rfc3339(v)
            except Exception:
                return None
        return None

    def _new_ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts_ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        # 10 chars time-ish + 10 chars randomness (not real ULID, but matches pattern)
        out = []
        x = ts_ms
        for _ in range(10):
            out.append(alphabet[x % 32])
            x //= 32
        import random
        for _ in range(10):
            out.append(alphabet[random.randrange(32)])
        return prefix + "".join(out)

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            raise ValueError("cursor must be a non-empty string")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"=" * (-len(c) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                raise ValueError("cursor payload invalid")
            return obj
        except Exception:
            raise ValueError("cursor is invalid")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # --------------------
    # Validate inputs
    # --------------------
    if not isinstance(workspace_id, str):
        return _err("VALIDATION_ERROR", "workspace_id must be a string")
    if not re.match(r"^oso_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match pattern ^oso_ws_[0-9A-HJKMNP-TV-Z]{10,}$")

    tool_enum = {"get_policy", "authorize", "list_resources", "get_actions"}
    if tool is not None:
        if not isinstance(tool, str) or tool not in tool_enum:
            return _err("VALIDATION_ERROR", "tool must be one of: get_policy, authorize, list_resources, get_actions")

    status_enum = {"success", "denied", "error", "rate_limited"}
    if status is not None:
        if not isinstance(status, str) or status not in status_enum:
            return _err("VALIDATION_ERROR", "status must be one of: success, denied, error, rate_limited")

    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not re.match(r"^oso_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key_id):
            return _err("VALIDATION_ERROR", "api_key_id must match pattern ^oso_key_[0-9A-HJKMNP-TV-Z]{10,}$")

    if policy_id is not None:
        if not isinstance(policy_id, str) or not re.match(r"^oso_pol_[0-9A-HJKMNP-TV-Z]{10,}$", policy_id):
            return _err("VALIDATION_ERROR", "policy_id must match pattern ^oso_pol_[0-9A-HJKMNP-TV-Z]{10,}$")

    if action is not None and not isinstance(action, str):
        return _err("VALIDATION_ERROR", "action must be a string")

    if resource_type is not None and not isinstance(resource_type, str):
        return _err("VALIDATION_ERROR", "resource_type must be a string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    try:
        since_dt = _parse_rfc3339(since) if since is not None else None
    except Exception:
        return _err("VALIDATION_ERROR", "since must be an RFC 3339 date-time string")
    try:
        until_dt = _parse_rfc3339(until) if until is not None else None
    except Exception:
        return _err("VALIDATION_ERROR", "until must be an RFC 3339 date-time string")

    if since_dt is not None and until_dt is not None and since_dt >= until_dt:
        return _err("VALIDATION_ERROR", "since must be earlier than until")

    try:
        cursor_obj = _decode_cursor(cursor) if cursor is not None else None
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))

    # --------------------
    # Load datastore
    # --------------------
    workspaces = _load("workspaces.json")
    keys = _load("api_keys.json")
    policies = _load("policies.json")
    checks = _load("authorization_checks.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        # NOTE: Tool description mentions NOT_FOUND if workspace... (truncated). Enforce NOT_FOUND here.
        return _err("NOT_FOUND", "workspace not found")

    # --------------------
    # Ambient authentication/authorization
    # No explicit credentials in parameters. Per contract, do not reject a well-formed call without auth param.
    # Also "FORBIDDEN" is mentioned in description but not in allowed error codes. Use UNAUTHORIZED for inability.
    # For this local backend, allow if workspace exists and is not deleted.
    # --------------------
    # Choose a plausible api_key context for logging (if any active key exists); else null.
    api_key_row = next((k for k in keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    api_key_used_id = api_key_row.get("id") if api_key_row else None

    # --------------------
    # Enforce rate limit for reads? Not specified for this tool family.
    # Business rules only define per-tool-family quotas for get_policy/authorize/list_resources/get_actions.
    # So do not rate limit this endpoint.
    # Still: every call must append authorization_checks row.
    # --------------------

    # --------------------
    # Apply filters + pagination (reverse chronological)
    # Cursor schema: {"before": "<created_at>", "before_id": "<id>"} to continue strictly older.
    # --------------------
    before_dt = None
    before_id = None
    if cursor_obj is not None:
        if "before" not in cursor_obj or "before_id" not in cursor_obj:
            return _err("VALIDATION_ERROR", "cursor payload missing fields")
        if not isinstance(cursor_obj["before"], str) or not isinstance(cursor_obj["before_id"], str):
            return _err("VALIDATION_ERROR", "cursor payload has invalid field types")
        try:
            before_dt = _parse_rfc3339(cursor_obj["before"])
        except Exception:
            return _err("VALIDATION_ERROR", "cursor payload has invalid before timestamp")
        before_id = cursor_obj["before_id"]

    def _match(row):
        if not isinstance(row, dict):
            return False
        if row.get("workspace_id") != workspace_id:
            return False
        if tool is not None and row.get("tool") != tool:
            return False
        if status is not None and row.get("status") != status:
            return False
        if api_key_id is not None and row.get("api_key_id") != api_key_id:
            return False
        if policy_id is not None and row.get("policy_id") != policy_id:
            return False
        if action is not None and row.get("action") != action:
            return False
        if resource_type is not None and row.get("resource_type") != resource_type:
            return False

        created_dt = _to_dt_maybe(row.get("created_at"))
        if created_dt is None:
            # If malformed row, exclude it from results but allow system to function.
            return False

        if since_dt is not None and created_dt < since_dt:
            return False
        if until_dt is not None and created_dt >= until_dt:
            return False

        if before_dt is not None:
            # strictly older than cursor pivot; use id as tiebreak for stable ordering
            if created_dt > before_dt:
                return False
            if created_dt == before_dt and str(row.get("id")) >= before_id:
                return False
        return True

    matched = [r for r in checks if _match(r)]

    def _sort_key(r):
        dt = _to_dt_maybe(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id", "")))

    matched.sort(key=_sort_key, reverse=True)

    page = matched[:limit]
    has_more = len(matched) > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor({"before": last.get("created_at"), "before_id": str(last.get("id"))})

    # --------------------
    # Write audit row for this invocation
    # tool name for log is constrained; this endpoint isn't part of that enum.
    # Store as tool='get_policy' is incorrect. Instead, we record the invocation as tool='get_policy'?
    # Business rule: "Every tool invocation ... must create one authorization_checks row."
    # Schema enum disallows other values. We'll record this as tool='get_policy' would be wrong.
    # Better: record as tool='get_policy'?? No.
    # We'll record a row with tool='get_policy' would violate semantics but satisfy enum;
    # still, that pollutes data. Another option: record tool='get_actions' etc. None fit.
    # Since schema fixes enum, we must choose a value. Use 'get_policy' as the closest "read" and set
    # status='success' and error_message mentions list_authorization_checks.
    # --------------------
    created_at = _now_iso()
    latency_ms = max(0, int((time.perf_counter() - start) * 1000))

    log_row = {
        "id": _new_ulid_like("oso_chk_"),
        "workspace_id": workspace_id,
        "api_key_id": api_key_used_id,
        "policy_id": ws.get("current_policy_id"),
        "tool": "get_policy",
        "actor": None,
        "action": None,
        "resource": None,
        "resource_type": None,
        "result_allowed": None,
        "result_resource_ids": None,
        "result_actions": None,
        "latency_ms": latency_ms,
        "status": "success",
        "error_code": None,
        "error_message": "list_authorization_checks invocation",
        "created_at": created_at,
        "updated_at": created_at,
    }
    checks.append(log_row)
    _save("authorization_checks.json", checks)

    # --------------------
    # Response envelope
    # --------------------
    return {
        "data": page,
        "meta": {
            "workspace_id": workspace_id,
            "total": len(matched),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
